use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\Gateway\UserRoleAssignmentQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\Gateway\UserRoleAssignmentSlide;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\Gateway\UserRoleAssignmentCommandRepositoryGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserRoleAssignmentVisibilityService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserRoleAssignmentQueryRepositoryGateway $readGateway,
        private readonly UserRoleAssignmentCommandRepositoryGateway $writeGateway,
        private readonly UserVisibilityService $userVisibilityService,
        private readonly RelyingPartyVisibilityService $relyingPartyVisibilityService,
        private readonly TrustedClientVisibilityService $trustedClientVisibilityService,
        private readonly RoleVisibilityService $roleVisibilityService
    ) {
    }

    public function prepareVisibleDataInList(UserRoleAssignment $content): UserRoleAssignmentAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(UserRoleAssignment $content): UserRoleAssignmentAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(UserRoleAssignmentAttributes $attributes, ?UserRoleAssignment $original = null): UserRoleAssignmentAttributes
    {
        $this->logDebug("Copy with fixed for User role assignment");
        $span = $this->startSpan("Copy with fixed for  User role assignment");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new UserRoleAssignmentPresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(UserRoleAssignmentAttributes $attributes, ?UserRoleAssignment $original = null): UserRoleAssignmentAttributes
    {
        $this->logDebug("Copy with hidden for User role assignment");
        $span = $this->startSpan("Copy with hidden for  User role assignment");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|UserRoleAssignmentRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for User role assignment");
        $span = $this->startSpan("Check visibility of an iterator for  User role assignment");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new UserRoleAssignmentRef($value));
            } elseif ($value instanceof UserRoleAssignmentRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new UserRoleAssignmentFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(UserRoleAssignmentFilter $filter, ?UserRoleAssignmentCursor $cursor = null): UserRoleAssignmentSlide
    {
        $this->logDebug("List visibles for User role assignment");
        $span = $this->startSpan("List visibles for  User role assignment");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (UserRoleAssignment $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisibles(UserRoleAssignmentFilter $filter): int
    {
        $this->logDebug("Count visibles for User role assignment");
        $span = $this->startSpan("Count visibles for  User role assignment");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->readGateway->count($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisiblesForUpdate(UserRoleAssignmentFilter $filter, ?UserRoleAssignmentCursor $cursor = null): UserRoleAssignmentSlide
    {
        $this->logDebug("List visibles for update for User role assignment");
        $span = $this->startSpan("List visibles for update for  User role assignment");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
            return $result->slide(function (UserRoleAssignment $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(UserRoleAssignmentFilter $filter): int
    {
        $this->logDebug("Count visibles for update for User role assignment");
        $span = $this->startSpan("Count visibles for update for  User role assignment");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(UserRoleAssignmentRef $ref): ?UserRoleAssignment
    {
        $this->logDebug("Retrieve visible for User role assignment");
        $span = $this->startSpan("Retrieve visible for  User role assignment");
        try {
            $filter = new UserRoleAssignmentFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(UserRoleAssignmentRef $ref): ?UserRoleAssignment
    {
        $this->logDebug("Retrieve visible for update for User role assignment");
        $span = $this->startSpan("Retrieve visible for update for  User role assignment");
        try {
            $filter = new UserRoleAssignmentFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?UserRoleAssignmentRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for User role assignment");
        $span = $this->startSpan("Check fields for fix for User role assignment");
        try {
            $result = $this->dispatcher->dispatch(new UserRoleAssignmentCollectNonEditableFields(UserRoleAssignment::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?UserRoleAssignmentRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for User role assignment");
        $span = $this->startSpan("Check fields to hide for  User role assignment");
        try {
            $result = $this->dispatcher->dispatch(new UserRoleAssignmentCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function visiblesReferences(UserRoleAssignmentAttributes $attributes): UserRoleAssignmentAttributes
    {
        $this->logDebug("Check visibility of parent references for User role assignment");
        $span = $this->startSpan("Check visibility of parent references for  User role assignment");
        try {
            $user = $attributes->getUser();
            if (null !== $user && !$this->userVisibilityService->checkVisibility($user)) {
                throw new NotFoundException("Unknown User " . ($user->uid() ?? 'no-id'));
            }
            $relyingParty = $attributes->getRelyingParty();
            if (null !== $relyingParty && !$this->relyingPartyVisibilityService->checkVisibility($relyingParty)) {
                throw new NotFoundException("Unknown RelyingParty " . ($relyingParty->uid() ?? 'no-id'));
            }
            $trustedClient = $attributes->getTrustedClient();
            if (null !== $trustedClient && !$this->trustedClientVisibilityService->checkVisibility($trustedClient)) {
                throw new NotFoundException("Unknown TrustedClient " . ($trustedClient->uid() ?? 'no-id'));
            }
            $roles = $attributes->getRoles();
            if (null !== $roles) {
                $this->checkVisibilityForRoles($roles);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(UserRoleAssignmentFilter $filter): UserRoleAssignmentFilter
    {
        $this->logDebug("Compose visibility filter for User role assignment");
        $span = $this->startSpan("Compose visibility filter for  User role assignment");
        try {
            $result = $this->dispatcher->dispatch(new UserRoleAssignmentRestrictFilterToVisibility($filter));
            return $result->userRoleAssignmentFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function checkVisibilityForRoles(UserRoleAssignmentRolesListRef $items): UserRoleAssignmentRolesListRef
    {
        $this->logDebug("Copy with fixed for User role assignment");
        $span = $this->startSpan("Copy with fixed for  User role assignment");
        try {
            foreach ($items as $item) {
                if (null !== $item) {
                    $role = $item->getRole();
                    if (null !== $role && !$this->roleVisibilityService->checkVisibility($role)) {
                        throw new NotFoundException("Unknown Role " . ($role->uid() ?? 'no-id'));
                    }
                }
            }
            return $items;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(UserRoleAssignment $value): bool
    {
        $this->logDebug("Check if item is visible for User role assignment");
        $span = $this->startSpan("Check if item is visible for  User role assignment");
        try {
            $result = $this->dispatcher->dispatch(new UserRoleAssignmentVisibilityCheck(true, $value));
            return $result->visible;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function prepareVisibleDataCallback(UserRoleAssignment $content, bool $inlist): UserRoleAssignmentAttributes
    {
        $this->logDebug("Prepare hydration to visible data for User role assignment");
        $span = $this->startSpan("Prepare hydration to visible data for User role assignment");
        try {
            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new UserRoleAssignmentEnrichForView($content, $inlist, $attributes));
            return $result->getAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
